import {t,getLanguage} from './i18n.js';
import {Chess} from './vendor/chess.js';
import {hanging,pins,forkTargets,opposite,names} from './tactics.js';
import {escapeHTML as esc} from './settings.js';
import {drawBoard} from './mini-board.js';
export const goals={king:'Prima di muovere, controlla gli scacchi disponibili all’avversario.',hanging:'Prima di confermare, verifica quali tuoi pezzi rimangono attaccati e senza difesa.',fork:'Controlla se un pezzo avversario può attaccare due bersagli insieme.',pin:'Verifica quali pezzi proteggono il tuo re e non possono muoversi liberamente.',material:'Prima di uno scambio, conta attaccanti e difensori.',position:'Prima di muovere, scegli il pezzo meno attivo e cerca di migliorarlo.'};
export function planContext(history,color){const own=history.filter(m=>m.color===color).slice(-3);if(own.filter(m=>'nb'.includes(m.piece)&&m.from[1]===(color==='w'?'1':'8')).length>=2)return 'Stai sviluppando i pezzi: pensa ora a come farli collaborare.';if(own.filter(m=>m.piece==='p'&&'de'.includes(m.to[0])).length>=2)return 'Hai avanzato i pedoni centrali: controlla che i pezzi li sostengano.';const a=own.at(-2),b=own.at(-1);if(a&&b&&a.to===b.from&&a.piece===b.piece)return 'Hai mosso ancora lo stesso pezzo: dai uno sguardo anche a quelli rimasti indietro.';return ''}
export function visualFacts(move){const c=new Chess(move.after),marks=new Set(),facts=[];for(const p of hanging(c,move.color).slice(0,2)){marks.add(p.square);c.attackers(p.square,opposite(move.color)).forEach(s=>marks.add(s));facts.push(getLanguage()==='it'?`Il ${names[p.type]} in ${p.square} è attaccato e non è difeso da altri tuoi pezzi.`:t('c.loose',[t(names[p.type]),p.square]))}for(const pin of pins(c,opposite(move.color)).slice(0,1)){[pin.attacker.square,pin.pinned.square,pin.king].forEach(s=>marks.add(s));facts.push(getLanguage()==='it'?`Il pezzo in ${pin.pinned.square} è inchiodato al re.`:t('c.pin',[pin.pinned.square,pin.attacker.square]))}const targets=forkTargets(c,move.to);if(targets.length>=2){marks.add(move.to);targets.forEach(p=>marks.add(p.square));facts.push(getLanguage()==='it'?`Il pezzo in ${move.to} attacca ${targets.map(p=>p.square).join(' e ')}. Questo non garantisce un guadagno di materiale.`:t('c.fork',[move.to,...targets.slice(0,2).map(p=>p.square)]))}if(!facts.length){marks.add(move.to);facts.push(getLanguage()==='it'?`La casa evidenziata è ${move.to}, dove hai portato il pezzo. Non emerge un doppio attacco o un pezzo indifeso dai controlli geometrici semplici: considera il piano e la valutazione.`:t('c.visual',[move.to]))}return {marks:[...marks],facts}}
export function addWhy(host,move){if(!move)return;const d=document.createElement('details');d.className='why-detail';d.innerHTML='<summary>Mostrami perché</summary>';d.addEventListener('toggle',()=>{if(!d.open||d.dataset.ready)return;d.dataset.ready='1';const {marks,facts}=visualFacts(move),board=document.createElement('div');board.className='board why-board';d.insertAdjacentHTML('beforeend','<p>Posizione subito dopo la tua mossa, prima della risposta.</p>');d.append(board);drawBoard(board,new Chess(move.after),{disabled:true,flipped:move.color==='b'});for(const sq of marks)board.querySelector(`[data-sq="${sq}"]`)?.classList.add('why-mark');for(const fact of facts){const el=document.createElement('p');el.textContent=fact;d.append(el)}});host.append(d)}
export function gameSummary(details,side){
 const own=details.filter(d=>(!side||d.side===side)&&Number.isFinite(d.loss)&&Number.isFinite(d.accuracy));
 const errors=own.filter(d=>d.loss>.05).sort((a,b)=>b.loss-a.loss);
 const themes=new Map();
 for(const d of errors){const x=themes.get(d.theme)||{sum:0,max:0};x.sum+=d.loss;x.max=Math.max(x.max,d.loss);themes.set(d.theme,x);}
 // Decisive losses take precedence over a collection of tiny positional errors.
 const decisive=errors.find(d=>d.loss>=.2&&goals[d.theme]);
 const theme=decisive?.theme||[...themes].sort((a,b)=>(b[1].sum-a[1].sum)||(b[1].max-a[1].max))[0]?.[0];
 return {moments:errors.slice(0,3),best:[...own].sort((a,b)=>b.accuracy-a.accuracy)[0],goal:goals[theme]||'Nella prossima partita, controlla scacchi, catture e minacce prima di ogni mossa.'};
}
export function summaryHTML(details,side){
 const s=gameSummary(details,side);
 if(!s.best)return '<h3>Riepilogo in preparazione</h3><p>Non ci sono ancora mosse analizzate per il colore selezionato.</p>';
 const label=m=>`${new Chess(m.fen).moveNumber()}${m.side==='w'?'.':'…'} ${m.san}`;
 return `<h3>${s.moments.length?'Momenti su cui lavorare':'Nessun errore rilevante rilevato'}</h3>${s.moments.length?`<ul>${s.moments.map(m=>`<li><strong>${esc(label(m))}</strong> · precisione ${m.accuracy.toFixed(1)}/100 · una scelta su cui lavorare</li>`).join('')}</ul>`:'<p>Tra le mosse analizzate non emergono perdite significative secondo i criteri della revisione.</p>'}<p><strong>${side?'La tua scelta più precisa':'La scelta più precisa'}:</strong> ${esc(label(s.best))}.</p><p><strong>Il prossimo obiettivo:</strong> ${esc(s.goal)}</p><small>Riepilogo delle mosse analizzate${side?' del tuo colore':', di entrambi i colori'}. Precisione stimata dal motore.</small>`;
}
export const ENDGAMES=[{name:'Opposizione e pedone',fen:'8/8/4k3/4P3/4K3/8/8/8 w - - 0 1',goal:'Valuta la distanza tra i re e il momento giusto per avanzare.'},{name:'Corsa alla promozione',fen:'8/k7/2P5/4K3/8/8/8/8 w - - 0 1',goal:'Coordina re e pedone, senza affrettare la spinta.'},{name:'Re e torre',fen:'6k1/8/8/8/8/5K2/1R6/8 w - - 0 1',goal:'Usa la torre per limitare il re avversario e avvicina il tuo.'},{name:'Re e donna',fen:'6k1/8/8/8/8/1Q3K2/8/8 w - - 0 1',goal:'Riduci lo spazio al re avversario, facendo attenzione allo stallo.'}];
